-- Accounting receivables are generated by invoices. Corrections start at that source.
do $$ declare f text;anchor text;begin
 anchor:='perform pg_advisory_xact_lock(hashtextextended(''business:''||a.tenant_id,0));';
 select pg_get_functiondef('public.business_save_record(text,text,text,uuid,integer,jsonb,uuid,text)'::regprocedure) into f;
 if strpos(f,anchor)=0 then raise exception 'Review save command before upgrading';end if;
 f:=replace(f,anchor,anchor||E'\n if p_kind=''receivables'' and exists(select 1 from public.business_tenants where id=a.tenant_id and features ? ''accounting'') then raise exception ''BUSINESS_RECORD_LOCKED'';end if;');execute f;
 select pg_get_functiondef('public.business_record_action(text,text,text,uuid,integer,text,text,uuid,text)'::regprocedure) into f;
 if strpos(f,anchor)=0 then raise exception 'Review record action before upgrading';end if;
 f:=replace(f,anchor,anchor||E'\n if p_kind=''receivables'' and exists(select 1 from public.business_tenants where id=a.tenant_id and features ? ''accounting'') then raise exception ''BUSINESS_RECORD_LOCKED'';end if;');execute f;
end $$;
